@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=1364  cases=77
@exercises configManager (h.cm), arrangeView (av), arrangeManager (am), commandManager (h.cmgr)
@surface   cm:set, av:tracksTakes, av:tidyRows, am:resizeTake, am:tracksTakes, cmgr:push, av:cursorRow, av:cursorCol, av:setCursor, av:setBeatPerRow, av:setCursorAt, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, am:deleteTake, av:pruneSlots, av:trackSlots, av:seedTidy, av:keyForSlot, av:tidyRenameBase, av:tidyDropBase, av:tidyAddBase, av:tidySlots, av:focus, av:setFocus, cmgr:invoke, av:lassoCandidate, av:selectionSet, av:isSelected, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:dragCandidate, av:commitDrag, av:hitTake, am:trimHead, am:loopRangeQN, am:editCursorQN, av:cursorTake, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetSetRepeat

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 18-40
      -- Build an av over a fake project. items: list of {track, name, pos, len?};
      -- an item naming a srcFile lands as audio rather than MIDI.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 42-44
  @fn tidySlots(av)  @ 54-57
  @fn tidyPreviews(av, assignment)  @ 59-63
  @fn mkTrimmable(harness)  @ 67-74
      -- One four-row take at rows 2..5, with four rows of source left over: enough
      -- room for the head to walk in and for the tail to grow.

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 95-103
  @case 'setCursorAt lands the caret on the row holding a project QN'  [harness]  @ 108-115
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 119-125
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 129-136
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 140-148
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 152-162
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 166-177
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 181-190
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 194-205
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 209-217
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 221-229
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 233-242
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 246-258
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 262-276
  @case 'a prune takes the palette focus down with the slot it lost'  [harness]  @ 280-292
  @case 'a prune leaves the palette focus alone when its slot still stands'  [harness]  @ 296-307
  @case 'tidyRows joins each MIDI slot to its key, its base and the name a tidy writes'  [harness]  @ 311-326
  @case 'a base rename carries its members, and a rename onto another base merges the two'  [harness]  @ 330-351
  @case 'deleting a base pins its members at the names they hold'  [harness]  @ 355-369
  @case 'an added base takes no members until a row picks it'  [harness]  @ 373-393
  @case 'a tidy renames the track\'s slots, and the palette focus stands'  [harness]  @ 397-413
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 417-426
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 430-446
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 450-466
  @case 'a held selection wins over the cursor take'  [harness]  @ 470-489
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 493-509
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 513-526
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 530-541
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 545-559
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 563-575
  @case 'a bare cursor move clears the selection'  [harness]  @ 579-589
  @case 'Home clears the selection like any other bare nav'  [harness]  @ 593-603
  @case 'Tab walks down the column, stopping at each start and each free row after a take'  [harness]  @ 607-625
  @case 'abutting takes collapse their shared boundary to one Tab stop'  [harness]  @ 629-640
  @case 'Shift+Tab walks back up, snapping to the start of the take it is inside'  [harness]  @ 644-658
  @case 'Tab only sees the takes in the cursor column'  [harness]  @ 662-675
  @case 'Tab clears the selection like any other bare nav'  [harness]  @ 679-690
  @case 'an edit's own cursor advance keeps the selection'  [harness]  @ 694-705
  @case 'the pooled duplicate clears the selection and lands the caret on the copy'  [harness]  @ 709-726
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 730-748
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 752-763
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 767-777
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 781-795
  @case 'delete and retreat puts the caret on the start row of what is left above it'  [harness]  @ 799-817
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 821-838
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 842-857
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 861-874
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 878-889
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 893-907
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 911-924
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 928-945
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 949-962
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 966-984
  @case 'hitTake reports each edge band and the move region between them'  [harness]  @ 990-1000
  @case 'an audio take has no head band — its start edge moves'  [harness]  @ 1004-1011
  @case 'a head drag walks the start in and holds the end'  [harness]  @ 1015-1029
  @case 'a head drag stops at the origin and one row short of the end'  [harness]  @ 1033-1042
  @case 'a tail drag on a trimmed take lands its end where it was dragged'  [harness]  @ 1046-1056
  @case 'loop to item brackets the take under the arrange cursor'  [harness]  @ 1062-1078
  @case 'loop to item takes the selection over the cursor, and spans a block'  [harness]  @ 1082-1099
  @case 'a cursor-driven replace leaves nothing selected'  [harness]  @ 1103-1115
  @case 'a replace of a selected take hands the selection to the replacement'  [harness]  @ 1119-1134
  @case 'a replace of a selection away from the cursor leaves the cursor alone'  [harness]  @ 1138-1150
  @case 'with advance-by-length armed, a drop advances by the take it placed'  [harness]  @ 1156-1169
  @case 'advance-by-length reads the clipped length, not the slot length'  [harness]  @ 1173-1186
  @case 'a second Ctrl-` puts the drop advance back on arrangeAdvanceBy'  [harness]  @ 1190-1204
  @case 'the caret on a start row moves the head down, holding the end still'  [harness]  @ 1211-1220
  @case 'the split key cuts the take at the caret and leaves the caret on the lower half'  [harness]  @ 1224-1234
  @case 'a split on the start row has nothing to cut'  [harness]  @ 1238-1244
  @case 'the caret off the start row moves the tail, leaving the head alone'  [harness]  @ 1248-1257
  @case 'Up on the start row hands back a row of head, taking the caret with it'  [harness]  @ 1261-1271
  @case 'a head at the origin refuses to grow, and the caret holds'  [harness]  @ 1275-1284
  @case 'the take under the cursor carries the source its box hides'  [harness]  @ 1288-1299
  @case 'a head trim is floored at one rendered row'  [harness]  @ 1303-1313
  @case 'a tail shrink never parks the caret on the head row'  [harness]  @ 1317-1330
  @case 'the armed edge is decided once, from the take the caret stands on'  [harness]  @ 1334-1349
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 1353-1362

